SELECT scope_type, COUNT(DISTINCT promotion_id) AS promotion_count
FROM agent_v3_promotion_offer_view WHERE agent_v3_promotion_offer_view.store_id = ANY(:allowedStoreIds) GROUP BY scope_type
LIMIT 100;

SELECT transfer_id, transfer_no, product_count
FROM ask_data_transfer_status_view WHERE ask_data_transfer_status_view.store_id = ANY(:allowedStoreIds) ORDER BY product_count DESC
LIMIT 10;
